CREATE COLUMN TABLE "TEST_AP"."OTPW" ("AbsEntry" INTEGER CS_INT NOT NULL , "WizNumber" INTEGER CS_INT, "WizName" NVARCHAR(50) NOT NULL , "WizStatus" NVARCHAR(1) DEFAULT 'S', "CreateDate" LONGDATE CS_LONGDATE, "SaveDate" LONGDATE CS_LONGDATE, "ExecDate" LONGDATE CS_LONGDATE, "UserSign" SMALLINT CS_INT, "Series" INTEGER CS_INT, "JETransId" INTEGER CS_INT, "WizDate" LONGDATE CS_LONGDATE, "RG23APart2" INTEGER CS_INT, "RG23CPart2" INTEGER CS_INT, "SeqCode" SMALLINT CS_INT, "Serial" INTEGER CS_INT, "SeriesStr" NVARCHAR(3), "SubStr" NVARCHAR(3), PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTPW_NAME" ON "TEST_AP"."OTPW" ( "WizName" ASC )